-- Dev-only catalog rows for Gun Run on the LAN (entry served by pnpm --filter @rally/game-gunrun dev on :5184,
-- strictPort). Generated from `publish-game gunrun --dry-run` (publish-plan.json): the games row, the manifest, the
-- `wins` (total) / `kills` (best) boards and the five achievements; art is left out (the dry run's CDN URLs are
-- placeholders; a real publish uploads it). Replace 10.0.0.201 with the PC LAN IP. Re-runnable. The game server must
-- be v4 (the `gunrun` room). The real publish adds 0.1.0 next to this -dev version and repoints current_version_id.
insert into public.games (id,title,description,genres,screenshots,icon_url,cover_url,engine,orientation,min_players,max_players,modes,age_rating,min_app_version,status)
values ('gunrun','Gun Run','Every kill hands you the next gun. Up to eight players drop into a sunny container yard and race up the ladder: pistol, revolver, SMG, shotgun, assault rifle, sniper, grenade launcher, rocket launcher, and finally the knife. Three kills promote you; one kill with the knife wins the match, and a stab sends the victim down a rung. Twin-stick shooting, exploding barrels, med kits and quick respawns. The boards keep your total wins and your most kills in a single match.',array['action','shooter']::text[],'{}'::text[],null,null,'playcanvas','landscape',2,8,array['quick','browser','private']::public.game_mode[],'12+','0.0.0','published')
on conflict (id) do update set title=excluded.title, description=excluded.description, genres=excluded.genres, min_players=excluded.min_players, max_players=excluded.max_players, modes=excluded.modes, age_rating=excluded.age_rating, status='published';

insert into public.game_versions (game_id,version,entry_url,manifest,sha256,size_bytes)
