on conflict (game_id,version) do update set entry_url=excluded.entry_url, manifest=excluded.manifest;

update public.games set current_version_id=(select id from public.game_versions where game_id='gunrun' and version='0.1.0-dev') where id='gunrun';

insert into public.leaderboards (game_id,key,sort,period,max_score_per_minute,mode) values ('gunrun','wins','desc','alltime',null,'total') on conflict (game_id,key) do update set mode=excluded.mode;
insert into public.leaderboards (game_id,key,sort,period,max_score_per_minute,mode) values ('gunrun','kills','desc','alltime',null,'best') on conflict (game_id,key) do update set mode=excluded.mode;
